#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    // Test case
    Eigen::Vector3d A(0.0, 0.0, 0.0);
    Eigen::Vector3d B(2.0, 0.0, 0.0);
    double E = 200e9;
    double Area = 0.01;
    double G = 76.923e9;
    double J = 5e-6;

    Eigen::Vector3d d = A - B;
    double XL = d.norm();

    Eigen::Vector3d XN = d / XL;

    double DSCL = Area * E / XL;
    double DSCR = J * G / XL;

    Eigen::Matrix3d N = XN * XN.transpose();

    Eigen::MatrixXd KE = Eigen::MatrixXd::Zero(6, 6);

    // Axial block (rows/cols 0-2)
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            KE(i, j) = DSCL * N(i, j);

    // Torsional block (rows/cols 3-5)
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            KE(3 + i, 3 + j) = DSCR * N(i, j);

    // Output JSON
    std::cout << std::setprecision(6) << std::scientific;
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 6; ++i) {
        std::cout << "[";
        for (int j = 0; j < 6; ++j) {
            std::cout << KE(i, j);
            if (j < 5) std::cout << ",";
        }
        std::cout << "]";
        if (i < 5) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
